with flattened_attrs as (select id, coupon_codes, items, array_max(transform(items, x -> x.price)) as max_item_price, exists(items, x -> x.price > 100) as has_premium_item, coalesce(ship_to.country, 'UNKNOWN') as country_or_unknown, array_contains(map_keys(attributes), 'weight_kg') as has_weight_kg from carts where array_contains(coupon_codes, 'WELCOME5')) select case when max_item_price >= 213 then 'HIGH' else 'LOW' end as max_item_price_tier, max(max_item_price) as max_max_item_price, approx_percentile(max_item_price, 0.95) as max_item_price_p95, count(*) as num_rows from flattened_attrs group by rollup (case when max_item_price >= 213 then 'HIGH' else 'LOW' end);
